    private static bool TryCreateOrder(string row, HashSet<string> seen, out Order order)
    {
        order = null!;
        if (string.IsNullOrWhiteSpace(row))
            return false;

        var parts = row.Split(',');
        if (parts.Length < 4)
            return false;

        var recordType = parts[0].Trim();
        var reference = parts[1].Trim();
        if (reference.Length == 0 || !seen.Add(reference))
            return false;

        order = CreateOrder(recordType, reference)!;
        if (order is null)
            return false;

        AddLines(order, parts);
        return order.Lines.Count > 0;
    }

    private static Order? CreateOrder(string recordType, string reference) => recordType switch
    {
        "H" or "ORDER" => new Order { Reference = reference, Channel = OrderChannel.Web },
        "M" => new Order { Reference = reference, Channel = OrderChannel.Marketplace },
        _ => null
    };

    private static void AddLines(Order order, string[] parts)
    {
        for (var i = 2; i + 1 < parts.Length; i += 2)
        {
            var sku = parts[i].Trim();
            if (sku.Length == 0)
                continue;
